import hashlib
from contextlib import contextmanager
from pathlib import Path
from typing import Protocol


class Storage(Protocol):
    def object_path(self, key: str) -> Path: ...
    def part_path(self, upload_id: str, number: int) -> Path: ...


class LocalStorage:
    """Development adapter. Keys are generated by the server, never by the client."""

    remote = False
    backend = "local"

    def __init__(self, root: Path):
        self.root = root.resolve()
        self.root.mkdir(parents=True, exist_ok=True)

    def object_path(self, key: str) -> Path:
        target = (self.root / key).resolve()
        if not target.is_relative_to(self.root):
            raise ValueError("storage key escaped root")
        target.parent.mkdir(parents=True, exist_ok=True)
        return target

    def part_path(self, upload_id: str, number: int) -> Path:
        return self.object_path(f"parts/{upload_id}/{number}")

    def publish(self, key, source, content_type):
        import shutil
        from uuid import uuid4

        target = self.object_path(key)
        temporary = target.with_name(target.name + "." + str(uuid4()) + ".tmp")
        try:
            shutil.copyfile(source, temporary)
            temporary.replace(target)
        finally:
            if temporary.exists():
                temporary.unlink()

    @contextmanager
    def materialize(self, file):
        path = self.object_path(file.object_key)
        if not path.is_file():
            from app.core.errors import BusinessError

            raise BusinessError("STORAGE_UNAVAILABLE", "原始文件不可读取", 503, retryable=True)
        yield path


def file_hash(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def build_storage(settings):
    if settings.storage_backend == "cos":
        from app.integrations.cos import CosStorage

        return CosStorage(settings)
    return LocalStorage(settings.storage_root)
